ALTER TABLE "customer_subscriptions" DROP CONSTRAINT IF EXISTS "customer_subscriptions_cryptomus_invoice_check";--> statement-breakpoint
ALTER TABLE "customer_subscriptions" ADD COLUMN IF NOT EXISTS "cryptomus_invoice_expires_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "customer_subscriptions" ADD CONSTRAINT "customer_subscriptions_cryptomus_invoice_check" CHECK (("customer_subscriptions"."payment_provider" IS NULL AND "customer_subscriptions"."cryptomus_invoice_uuid" IS NULL AND "customer_subscriptions"."cryptomus_payment_url" IS NULL AND "customer_subscriptions"."cryptomus_invoice_expires_at" IS NULL) OR ("customer_subscriptions"."payment_provider" = 'cryptomus' AND (("customer_subscriptions"."cryptomus_invoice_uuid" IS NULL AND "customer_subscriptions"."cryptomus_payment_url" IS NULL AND "customer_subscriptions"."cryptomus_invoice_expires_at" IS NULL) OR ("customer_subscriptions"."cryptomus_invoice_uuid" IS NOT NULL AND "customer_subscriptions"."cryptomus_payment_url" IS NOT NULL AND "customer_subscriptions"."cryptomus_invoice_expires_at" IS NOT NULL))));
